INSERT INTO sys_menu (parent_id,path,name,component,title,type,permission,created_at,updated_at,created_by) SELECT 0,'/system/service-upgrade/index','service-upgrade','system/service-upgrade/index','服务升级',2,'',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE path='/system/service-upgrade/index' AND name='service-upgrade');
INSERT INTO sys_menu (parent_id,path,name,component,title,type,permission,created_at,updated_at,created_by) SELECT m.id,'','ServiceUpgradeRead','', '查看服务升级',3,'system:upgrade:read',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM sys_menu m WHERE m.path='/system/service-upgrade/index' AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission='system:upgrade:read');
INSERT INTO sys_menu (parent_id,path,name,component,title,type,permission,created_at,updated_at,created_by) SELECT m.id,'','ServiceUpgradeManage','', '管理服务升级',3,'system:upgrade:manage',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM sys_menu m WHERE m.path='/system/service-upgrade/index' AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission='system:upgrade:manage');
INSERT INTO sys_api (title,path,method,api_group,created_at,updated_at,created_by) SELECT v.title,v.path,v.method,'服务升级',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM (SELECT '查看升级状态' title,'/api/system/upgrade/status' path,'GET' method UNION ALL SELECT '查看无人值守策略','/api/system/upgrade/policy','GET' UNION ALL SELECT '查看迁移计划','/api/system/upgrade/migration-plan','GET' UNION ALL SELECT '检查在线升级','/api/system/upgrade/check','POST' UNION ALL SELECT '查看升级任务','/api/system/upgrade/tasks/:id','GET' UNION ALL SELECT '导入离线升级包','/api/system/upgrade/import','POST' UNION ALL SELECT '创建升级任务','/api/system/upgrade/tasks','POST' UNION ALL SELECT '修改无人值守策略','/api/system/upgrade/policy','PUT' UNION ALL SELECT '取消升级任务','/api/system/upgrade/tasks/:id/cancel','POST' UNION ALL SELECT '应用升级任务','/api/system/upgrade/tasks/:id/apply','POST' UNION ALL SELECT '回退升级任务','/api/system/upgrade/tasks/:id/rollback','POST') v WHERE NOT EXISTS (SELECT 1 FROM sys_api a WHERE a.path=v.path AND a.method=v.method);
INSERT INTO sys_menu_api (menu_id,api_id) SELECT m.id,a.id FROM sys_menu m CROSS JOIN sys_api a WHERE m.permission='system:upgrade:read' AND a.method IN ('GET','POST') AND a.path IN ('/api/system/upgrade/status','/api/system/upgrade/policy','/api/system/upgrade/migration-plan','/api/system/upgrade/check','/api/system/upgrade/tasks/:id') AND NOT EXISTS (SELECT 1 FROM sys_menu_api ma WHERE ma.menu_id=m.id AND ma.api_id=a.id);
INSERT INTO sys_menu_api (menu_id,api_id) SELECT m.id,a.id FROM sys_menu m CROSS JOIN sys_api a WHERE m.permission='system:upgrade:manage' AND a.method IN ('POST','PUT') AND a.path IN ('/api/system/upgrade/policy','/api/system/upgrade/import','/api/system/upgrade/tasks','/api/system/upgrade/tasks/:id/cancel','/api/system/upgrade/tasks/:id/apply','/api/system/upgrade/tasks/:id/rollback') AND NOT EXISTS (SELECT 1 FROM sys_menu_api ma WHERE ma.menu_id=m.id AND ma.api_id=a.id);
INSERT INTO sys_casbin_rule (ptype,v0,v1,v2,v3,v4,v5) SELECT 'p','role_1',a.path,a.method,'*','','' FROM sys_api a WHERE a.path IN ('/api/system/upgrade/status','/api/system/upgrade/policy','/api/system/upgrade/migration-plan','/api/system/upgrade/check','/api/system/upgrade/tasks/:id','/api/system/upgrade/import','/api/system/upgrade/tasks','/api/system/upgrade/tasks/:id/cancel','/api/system/upgrade/tasks/:id/apply','/api/system/upgrade/tasks/:id/rollback') AND NOT EXISTS (SELECT 1 FROM sys_casbin_rule r WHERE r.ptype='p' AND r.v0='role_1' AND r.v1=a.path AND r.v2=a.method);
